<?php use App\Domain\Transfers\TransferRules as Rules; ?>
<div class="transfers-workspace"><section class="admin-page-head"><div><p class="admin-kicker">INVENTARIO ENTRE SUCURSALES</p><h1>Transferencias</h1><p>Organiza los envíos entre sucursales y consulta el avance de cada solicitud.</p></div><?php if($canCreate):?><a class="admin-primary-button" data-admin-form-link href="/admin/transfers/create">+ Solicitar transferencia</a><?php endif?></section>
<section class="transfers-guide" aria-label="Proceso de transferencia"><div><span>01</span><div><h2>Solicita y aprueba</h2><p>Define origen, destino y mercancía. La aprobación aparta unidades en origen.</p></div></div><div><span>02</span><div><h2>Prepara y despacha</h2><p>Confirma la preparación y registra las cantidades que salen físicamente.</p></div></div><div><span>03</span><div><h2>Recibe en destino</h2><p>Confirma lo recibido para actualizar la existencia de la sucursal destino.</p></div></div></section><section class="admin-panel transfers-filters"><header><h2>Buscar transferencias</h2><p>Localiza un envío por folio, sucursal o estado.</p></header><form class="transfers-filter-grid" method="get" action="/admin/transfers"><label class="admin-field"><span>Folio o sucursal</span><input type="search" placeholder="Folio o nombre de sucursal" name="q" value="<?= e($q) ?>" maxlength="120"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><option value="">Todas autorizadas</option><?php foreach($branches as $b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="">Todos</option><?php foreach(Rules::LABELS as $key=>$label):?><option value="<?= e($key) ?>" <?= $status===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach?></select></label><div class="transfers-filter-actions"><button class="admin-secondary-button">Aplicar filtros</button><?php if($q!==''||$status!==''||$branchId):?><a class="transfers-text-link" href="/admin/transfers">Limpiar</a><?php endif?></div></form></section>
<section class="admin-panel admin-table-panel transfers-directory"><header class="transfers-directory-heading"><div><h2>Transferencias registradas</h2><p>Origen, destino y seguimiento de la mercancía.</p></div><span><?= e(count($page->items)) ?> en esta página</span></header><?php if(!$page->items):?><div class="transfers-empty"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4"/></svg><h3><?= ($q!==''||$status!==''||$branchId)?'Sin coincidencias':'Aún no hay transferencias registradas' ?></h3><p><?= ($q!==''||$status!==''||$branchId)?'Prueba con otro folio, sucursal o estado, o limpia los filtros.':'Comienza con una solicitud entre sucursales. Podrás aprobarla y dar seguimiento a su salida y recepción física.' ?></p><div class="transfers-empty-actions"><?php if($q!==''||$status!==''||$branchId):?><a class="admin-secondary-button" href="/admin/transfers">Limpiar filtros</a><?php elseif($canCreate):?><a class="admin-primary-button" data-admin-form-link href="/admin/transfers/create">Solicitar transferencia</a><?php endif?></div></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Folio / fecha</th><th>Origen</th><th>Destino</th><th>Estado</th><th>Responsable</th><th>Partidas</th><th>Acciones</th></tr></thead><tbody><?php foreach($page->items as $t):?><tr><td data-label="Folio / fecha"><div><?= e($t['folio']) ?><small><?= e($t['created_at']) ?> UTC</small></div></td><td data-label="Origen"><?= e($t['source_name']) ?></td><td data-label="Destino"><?= e($t['destination_name']) ?></td><td data-label="Estado"><span class="transfers-status" data-state="<?= e($t['status']) ?>"><?= e(Rules::LABELS[$t['status']]) ?></span></td><td data-label="Responsable"><?= e($t['actor_name']) ?></td><td data-label="Partidas"><?= e($t['item_count']) ?></td><td class="admin-actions"><a class="admin-secondary-button" data-admin-form-link href="/admin/transfers/detail?id=<?= e($t['id']) ?>">Abrir</a></td></tr><?php endforeach?></tbody></table></div><?php endif?><?php if($page->offset>0||$page->hasMore):?><nav class="admin-pagination" aria-label="Paginación"><?php $params=['q'=>$q,'status'=>$status,'branch_id'=>$branchId];if($page->offset>0):?><a href="?<?= e(http_build_query($params+['offset'=>max(0,$page->offset-25)])) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a href="?<?= e(http_build_query($params+['offset'=>$page->offset+25])) ?>">Siguiente</a><?php endif?></nav><?php endif?></section></div>
